/// Stops a Stream associated with a call. Set `Status` to `stopped`, and identify the Stream by its SID or the name used when it was created.
///
/// Stop a Stream using either the SID of the Stream resource or the `name` used when creating the resource
///
/// [accountSid] The SID of the
///   [Account](https://www.twilio.com/docs/iam/api/account) that created this
///   Stream resource.
/// [callSid] The SID of the
///   [Call](https://www.twilio.com/docs/voice/api/call-resource) the Stream
///   resource is associated with.
/// [sid] The SID or the `name` of the Stream resource to be stopped
Future<ApiV2010AccountCallStream> updateCallsStreams(ClientConfig config,
    {required String accountSid,
    required String callSid,
    required String sid,
    required StreamEnumUpdateStatus status,
    RequestOptions? requestOptions}) async {
  validateLength('AccountSid', accountSid, min: 34, max: 34);
  sdkValidatePattern('AccountSid', accountSid, '^AC[0-9a-fA-F]{32}\$');
  validateLength('CallSid', callSid, min: 34, max: 34);
  sdkValidatePattern('CallSid', callSid, '^CA[0-9a-fA-F]{32}\$');

  return (await sdkRequest<ApiV2010AccountCallStream>('POST',
          '/2010-04-01/Accounts/${Uri.encodeComponent(accountSid.toString())}/Calls/${Uri.encodeComponent(callSid.toString())}/Streams/${Uri.encodeComponent(sid.toString())}.json',
          config: config,
          body: {'Status': status},
          contentType: 'application/x-www-form-urlencoded',
          decoder: SdkResponseDecoder.json,
          operationId: 'updateCallsStreams',
          fromJsonRaw: (value) =>
              ApiV2010AccountCallStream.fromJson(value as Map<String, dynamic>),
          options: requestOptions))
      .data;
}
